// ─── CONNECTORS DATA (32 items) ───
export var CONNECTORS = [
  // ── Contrast: clause connectors ──
  {word:"Although",rule:"clause",ex:"Although sales dropped, profits increased.",tip:"Although + subject + verb (clause)."},
  {word:"Even though",rule:"clause",ex:"Even though it rained, the event was a success.",tip:"Even though + subject + verb (clause). Stronger than 'although'."},
  {word:"Whereas",rule:"clause",ex:"Whereas sales rose in Q1, they fell in Q2.",tip:"Whereas + clause (contrast between two facts)."},
  {word:"While",rule:"clause",ex:"While the report is accurate, it lacks detail.",tip:"While + clause (contrast or simultaneous action)."},
  {word:"Though",rule:"clause",ex:"The hotel was expensive, though the service was excellent.",tip:"Though + clause. Can come after the main clause (less formal than although)."},
  // ── Contrast: noun phrase connectors ──
  {word:"Despite",rule:"noun",ex:"Despite the delay, we met the deadline.",tip:"Despite + noun or -ing (no subject + verb)."},
  {word:"In spite of",rule:"noun",ex:"In spite of the bad weather, they went ahead.",tip:"In spite of + noun or -ing (same as despite)."},
  {word:"Regardless of",rule:"noun",ex:"Regardless of the cost, we must proceed.",tip:"Regardless of + noun. Means 'no matter what'."},
  // ── Contrast: sentence transition ──
  {word:"However",rule:"sentence",ex:"The budget was tight. However, we managed.",tip:"However = new sentence or after semicolon."},
  {word:"Nevertheless",rule:"sentence",ex:"Results were poor. Nevertheless, the team stayed motivated.",tip:"Nevertheless = new sentence. Formal register."},
  {word:"On the other hand",rule:"sentence",ex:"The price is high. On the other hand, the quality is excellent.",tip:"On the other hand = new sentence (contrasting perspective)."},
  // ── Cause: clause connectors ──
  {word:"Because",rule:"clause",ex:"Because the shipment was late, we lost the client.",tip:"Because + subject + verb (clause, gives the reason)."},
  {word:"Since",rule:"clause",ex:"Since costs have risen, we must adjust our budget.",tip:"Since + clause (causal, like 'because'). Also means 'from that time'."},
  {word:"As",rule:"clause",ex:"As the deadline approaches, the team is working overtime.",tip:"As + clause (cause or time). Context tells you which."},
  {word:"Now that",rule:"clause",ex:"Now that the merger is complete, we can plan ahead.",tip:"Now that + clause (cause linked to a new situation)."},
  // ── Cause: noun phrase connectors ──
  {word:"Due to",rule:"noun",ex:"Due to heavy traffic, the delivery was delayed.",tip:"Due to + noun phrase (not a full clause)."},
  {word:"Because of",rule:"noun",ex:"Because of the storm, the event was cancelled.",tip:"Because of + noun or -ing. (NOT 'because of it rained')."},
  {word:"Owing to",rule:"noun",ex:"Owing to budget constraints, hiring has been frozen.",tip:"Owing to + noun. Formal register."},
  // ── Result/Consequence: sentence ──
  {word:"Therefore",rule:"sentence",ex:"Demand rose; therefore, prices increased.",tip:"Therefore = new sentence or after semicolon (consequence)."},
  {word:"Consequently",rule:"sentence",ex:"The factory closed. Consequently, 200 jobs were lost.",tip:"Consequently = new sentence (result/consequence)."},
  {word:"As a result",rule:"sentence",ex:"Sales dropped. As a result, layoffs were announced.",tip:"As a result = new sentence (consequence)."},
  {word:"Thus",rule:"sentence",ex:"Costs exceeded the budget. Thus, the project was paused.",tip:"Thus = new sentence (formal consequence)."},
  // ── Addition: noun phrase ──
  {word:"In addition to",rule:"noun",ex:"In addition to his salary, he receives a bonus.",tip:"In addition to + noun or -ing."},
  {word:"Apart from",rule:"noun",ex:"Apart from the CEO, no one knew about the deal.",tip:"Apart from + noun. Means 'except for' or 'in addition to'."},
  // ── Addition: sentence ──
  {word:"Furthermore",rule:"sentence",ex:"The product is affordable. Furthermore, it is eco-friendly.",tip:"Furthermore = new sentence (adds information). Formal."},
  {word:"Moreover",rule:"sentence",ex:"The plan saves money. Moreover, it reduces waste.",tip:"Moreover = new sentence (adds stronger information)."},
  {word:"In addition",rule:"sentence",ex:"We offer free delivery. In addition, returns are free.",tip:"In addition = new sentence (not to be confused with 'in addition to' + noun)."},
  // ── Condition ──
  {word:"Unless",rule:"clause",ex:"Unless we receive payment by Friday, we will cancel the order.",tip:"Unless + clause. Means 'if not'. NEVER 'unless if'."},
  {word:"Provided that",rule:"clause",ex:"You may leave early, provided that your work is complete.",tip:"Provided that + clause. Means 'only if'."},
  {word:"As long as",rule:"clause",ex:"You can use the software as long as you have a valid license.",tip:"As long as + clause. Means 'on the condition that'."},
  // ── Purpose ──
  {word:"In order to",rule:"noun",ex:"In order to reduce costs, the company outsourced production.",tip:"In order to + base verb (purpose). More formal than 'to'."},
  {word:"So that",rule:"clause",ex:"We hired extra staff so that we could meet the deadline.",tip:"So that + subject + verb (purpose clause)."},
  // ─── NEW CONNECTORS (18 items) — paste after last entry in CONNECTORS ───

  // ── Contrast: additional ──
  {word:"Nonetheless",rule:"sentence",ex:"The risks were significant. Nonetheless, the board approved the project.",tip:"Nonetheless = nevertheless. New sentence or after semicolon. Formal register."},
  {word:"In contrast",rule:"sentence",ex:"Sales rose in Europe. In contrast, the Asian market declined.",tip:"In contrast = new sentence. Highlights a direct opposition between two facts."},
  {word:"Conversely",rule:"sentence",ex:"Exports increased this quarter. Conversely, domestic sales dropped.",tip:"Conversely = the opposite is true. New sentence. Very formal."},
  // ── Cause: additional ──
  {word:"Given that",rule:"clause",ex:"Given that demand has dropped, we should reduce production.",tip:"Given that + clause = considering the fact that. More formal than 'because'."},
  {word:"Seeing as",rule:"clause",ex:"Seeing as the budget is limited, we'll have to prioritize.",tip:"Seeing as + clause. Less formal alternative to 'given that'. Common in spoken English."},
  {word:"On account of",rule:"noun",ex:"The match was postponed on account of bad weather.",tip:"On account of + noun phrase. Formal equivalent of 'because of'."},
  // ── Result/Consequence: additional ──
  {word:"Hence",rule:"sentence",ex:"The contract was unsigned; hence, the deal fell through.",tip:"Hence = therefore. Very formal. New sentence or after semicolon."},
  {word:"Accordingly",rule:"sentence",ex:"Costs have risen sharply. Accordingly, prices will be adjusted.",tip:"Accordingly = as a logical result. New sentence. Implies a deliberate response."},
  {word:"For this reason",rule:"sentence",ex:"Our servers are outdated. For this reason, we are investing in new infrastructure.",tip:"For this reason = new sentence. Explicitly links cause to action."},
  // ── Addition: additional ──
  {word:"Besides",rule:"noun",ex:"Besides the salary, the package includes health insurance.",tip:"Besides + noun = in addition to. Also used as a sentence adverb: 'Besides, it's too late.'"},
  {word:"Not only...but also",rule:"clause",ex:"Not only did sales increase, but customer satisfaction also improved.",tip:"Not only + inverted verb...but also. Parallel structure. Emphasis connector."},
  {word:"As well as",rule:"noun",ex:"The manager, as well as the team leads, attended the workshop.",tip:"As well as + noun. Note: verb agrees with FIRST subject. 'The manager... attended' (singular)."},
  // ── Time / Sequence ──
  {word:"Subsequently",rule:"sentence",ex:"The error was discovered in May. Subsequently, a full audit was ordered.",tip:"Subsequently = after that, later. New sentence. Formal time sequence."},
  {word:"Meanwhile",rule:"sentence",ex:"The CEO was traveling. Meanwhile, the VP handled daily operations.",tip:"Meanwhile = at the same time. New sentence. Shows parallel events."},
  {word:"Prior to",rule:"noun",ex:"Prior to the merger, both companies operated independently.",tip:"Prior to + noun/-ing = before. 'Prior to joining' = before joining. Formal."},
  // ── Emphasis / Clarification ──
  {word:"In other words",rule:"sentence",ex:"The position has been eliminated. In other words, there will be layoffs.",tip:"In other words = rephrasing for clarity. New sentence."},
  {word:"Namely",rule:"sentence",ex:"Two departments were affected, namely Marketing and Finance.",tip:"Namely = specifically. Introduces specific examples of what was just mentioned."},
  {word:"That is to say",rule:"sentence",ex:"The policy applies to all contractors — that is to say, anyone not on the permanent payroll.",tip:"That is to say = in other words, more precisely. Clarification connector."},
];

